-- Schéma de départ. Aucune politique RLS n'est ouverte par défaut.
create extension if not exists pgcrypto;
create table if not exists public.centers(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now());
create table if not exists public.center_members(center_id uuid not null references public.centers(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'operator' check(role in ('admin','operator','viewer')),primary key(center_id,user_id));
create table if not exists public.formulas(id uuid primary key default gen_random_uuid(),center_id uuid not null references public.centers(id) on delete cascade,name text not null,materials jsonb not null default '{}'::jsonb,unique(center_id,name));
create table if not exists public.material_densities(center_id uuid not null references public.centers(id) on delete cascade,material_name text not null,density_kg_m3 numeric not null check(density_kg_m3>0),primary key(center_id,material_name));
create table if not exists public.trucks(id uuid primary key default gen_random_uuid(),center_id uuid not null references public.centers(id) on delete cascade,name text not null,active boolean not null default true,unique(center_id,name));
create table if not exists public.truck_daily_status(id uuid primary key default gen_random_uuid(),center_id uuid not null references public.centers(id) on delete cascade,truck_id uuid not null references public.trucks(id) on delete cascade,work_date date not null,is_working boolean not null,note text,updated_at timestamptz not null default now(),unique(truck_id,work_date));
create table if not exists public.stock_movements(id uuid primary key default gen_random_uuid(),center_id uuid not null references public.centers(id) on delete cascade,movement_date date not null,material_name text not null,movement_type text not null check(movement_type in ('in','out','adjust')),quantity_kg numeric not null check(quantity_kg>0),note text);
create table if not exists public.production_records(id uuid primary key default gen_random_uuid(),center_id uuid not null references public.centers(id) on delete cascade,production_date date not null,formula_id uuid references public.formulas(id) on delete set null,formula_name text not null,quantity_m3 numeric not null check(quantity_m3>0),reference text,note text);
do $$ declare t text; begin foreach t in array array['centers','center_members','formulas','material_densities','trucks','truck_daily_status','stock_movements','production_records'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
